/// <summary>
/// The <c>MyApplicationInsightsEventProperties</c> class contains all available event properties that can be used in the Application Insights telemetry.
/// </summary>
/// <remarks>
/// The names must be unique.
/// Please keep the list sorted alphabetically in ascending order.
/// </remarks>
public static final class ISMTelemetryProperties
{
    public static const str BatchJobId							= 'BatchJobId';
    public static const str BatchJobTaskId						= 'BatchJobTaskId';
    public static const str ChildBatchJobId 					= 'ChildBatchJobId';
    public static const str OrigStatus 		        = 'OrigStatus';
    public static const str NewStatus 		        = 'NewStatus';
    public static const str BatchJobName 		        = 'BatchJobName';
    public static const str Reccurence 		        = 'Reccurence';
    public static const str CreatedBy 		        = 'CreatedBy';
    public static const str ExecutingBy 		        = 'ExecutingBy';
    public static const str OrderType 		        = 'OrderType';
    public static const str StartDateTime 		        = 'StartDateTime';
    public static const str EndDateTime 		        = 'EndDateTime';
    public static const str RuntimeTask 		        = 'RuntimeTask';
    public static const str AOS 		        = 'AOS';
    public static const str CurrentUserId 		        = 'CurrentUserId';
    public static const str DataAreaId 		        = 'DataAreaId';
    public static const str BatchCaption 		        = 'BatchCaption';
    public static const str CallStack 		        = 'CallStack';
    public static const str ElapsedMilliseconds 		        = 'ElapsedMilliseconds';
    public static const str Error 		        = 'Error';
    public static const str ClassName 		        = 'ClassName';
    public static const str RetryCount 		        = 'RetryCount';
    public static const str ShowProgress 		        = 'ShowProgress';
    //DMF
    public static const str DefinitionGroup 		    = 'DefinitionGroup';
    public static const str Entity 		                = 'Entity';
    public static const str ExecutionId 		        = 'ExecutionId';
    public static const str NoOfRecords 		        = 'NoOfRecords';
    public static const str NumOfTargetNew 		        = 'NumOfTargetNew';
    public static const str FILEPATH 		    = 'FILEPATH';
    public static const str FILETYPE 		    = 'FILETYPE';
    public static const str NUMOFSTAGINGNEW 		    = 'NUMOFSTAGINGNEW';
    public static const str NumOfTargetUpdated 		    = 'NumOfTargetUpdated';
    public static const str NOOFTHREADS 		    = 'NOOFTHREADS';
    public static const str SEQUENCE 		    = 'SEQUENCE';
    public static const str TARGETSTATUS 		    = 'TARGETSTATUS';
    public static const str STAGINGSTATUS 		    = 'STAGINGSTATUS';
    public static const str STAGINGERRORCOUNT 		    = 'STAGINGERRORCOUNT';
    public static const str TARGETERRORCOUNT 		    = 'TARGETERRORCOUNT';
    public static const str NUMOFTARGETDELETED 		    = 'NUMOFTARGETDELETED';
    public static const str ERRORFILEID 		    = 'ERRORFILEID';
    public static const str CREATEDDATETIME 		    = 'CREATEDDATETIME';
    public static const str RecordsProcessed 		    = 'RecordsProcessed';
    public static const str ExportRowLimit 		    = 'ExportRowLimit';
    public static const str ExportRowLimitReached 		    = 'ExportRowLimitReached';
    public static const str Finalizing 		    = 'Finalizing';

      // sql

    public static const str SqlStatement 		    = 'SqlStatement';
    public static const str QueryPlan 		    = 'QueryPlan';

}
